@FunctionalInterface
interface Calc {
    int apply(int a, int b);
}

class Adder implements Calc {
    @Override
    public int apply(int a, int b) {
        return a + b;
    }
}

public class Main {
    public static void main(String[] args) {
        // 1. クラスを作る
        Calc c1 = new Adder();

        // 2. 匿名クラス
        Calc c2 = new Calc() {
            @Override
            public int apply(int a, int b) {
                return a + b;
            }
        };

        // 3. ラムダ式
        Calc c3 = (a, b) -> a + b;

        System.out.println(c1.apply(3, 4));
        System.out.println(c2.apply(3, 4));
        System.out.println(c3.apply(3, 4));
    }
}

