import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> base = List.of("banana", "apple", "fig", "date");

        List<String> a = new ArrayList<>(base);
        a.sort(Comparator.naturalOrder());
        System.out.println("辞書順      : " + a);

        List<String> b = new ArrayList<>(base);
        b.sort(Comparator.comparingInt(String::length));
        System.out.println("短い順      : " + b);

        List<String> c = new ArrayList<>(base);
        c.sort(Comparator.comparingInt(String::length).reversed());
        System.out.println("長い順      : " + c);

        List<String> d = new ArrayList<>(base);
        d.sort(Comparator.reverseOrder());
        System.out.println("辞書順の逆  : " + d);

        System.out.println("元のリスト  : " + base);
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("cc", "aa", "b", "bb"));

        List<String> onlyLength = new ArrayList<>(words);
        onlyLength.sort(Comparator.comparingInt(String::length));
        System.out.println("長さだけ    : " + onlyLength);

        List<String> withSecond = new ArrayList<>(words);
        withSecond.sort(Comparator.comparingInt(String::length)
                .thenComparing(Comparator.naturalOrder()));
        System.out.println("長さ→辞書順 : " + withSecond);

        List<String> byLambda = new ArrayList<>(words);
        byLambda.sort((s1, s2) -> {
            int byLength = Integer.compare(s1.length(), s2.length());
            return byLength != 0 ? byLength : s1.compareTo(s2);
        });
        System.out.println("ラムダで同じ: " + byLambda);
    }
}

